 * SPDX-License-Identifier: Apache-2.0
*/
import {Video} from '@google/genai';

export enum AppState {
  IDLE,
  LOADING,
  SUCCESS,
  ERROR,
}

export enum VeoModel {
  VEO_FAST = 'veo-3.1-fast-generate-preview',
  VEO = 'veo-3.1-generate-preview',
}

export enum AspectRatio {
  LANDSCAPE = '16:9',
  PORTRAIT = '9:16',
  SQUARE = '1:1',
}

export enum Resolution {
  P720 = '720p',
  P1080 = '1080p',
  P4K = '4k',
}

export enum GenerationMode {
  TEXT_TO_VIDEO = 'Text to Video',
  FRAMES_TO_VIDEO = 'Frames to Video',
  REFERENCES_TO_VIDEO = 'References to Video',
  EXTEND_VIDEO = 'Extend Video',
}

export enum VideoStyle {
  REALISTIC = 'Realistic',
  ANIME = 'Anime',
  RENDER_3D = '3D Render',
  CINEMATIC = 'Cinematic',
}

export interface ImageFile {
  file: File;
  base64: string;
}

export interface VideoFile {
  file: File;
  base64: string;
}

export interface GenerateVideoParams {
  prompt: string;
  model: VeoModel;
  aspectRatio: AspectRatio;
  resolution: Resolution;
  mode: GenerationMode;
  style?: VideoStyle;
  duration?: string; // e.g. "5s", "10s"
  startFrame?: ImageFile | null;
  endFrame?: ImageFile | null;
  referenceImages?: ImageFile[];
  styleImage?: ImageFile | null;
  inputVideo?: VideoFile | null;
  inputVideoObject?: Video | null;
  isLooping?: boolean;
}

/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
*/
import {Video} from '@google/genai';
import React, {useCallback, useEffect, useState} from 'react';
import ApiKeyDialog from './components/ApiKeyDialog';
import LoadingIndicator from './components/LoadingIndicator';
import PromptForm from './components/PromptForm';
import VideoResult from './components/VideoResult';
import {generateVideo} from './services/geminiService';
import {PlusIcon, WalletIcon} from './components/icons';
import {
  AppState,
  AspectRatio,
  GenerateVideoParams,
  GenerationMode,
  Resolution,
  VideoFile,
} from './types';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [lastConfig, setLastConfig] = useState<GenerateVideoParams | null>(
    null,
  );
  const [lastVideoObject, setLastVideoObject] = useState<Video | null>(null);
  const [lastVideoBlob, setLastVideoBlob] = useState<Blob | null>(null);
  const [showApiKeyDialog, setShowApiKeyDialog] = useState(false);

  const [initialFormValues, setInitialFormValues] =
    useState<GenerateVideoParams | null>(null);

  useEffect(() => {
    const checkApiKey = async () => {
      if (window.aistudio) {
        try {
          if (!(await window.aistudio.hasSelectedApiKey())) {
            setShowApiKeyDialog(true);
          }
        } catch (error) {
          console.warn(
            'aistudio.hasSelectedApiKey check failed, assuming no key selected.',
            error,
          );
          setShowApiKeyDialog(true);
        }
      }
    };
    checkApiKey();
  }, []);

  const showStatusError = (message: string) => {
    setErrorMessage(message);
    setAppState(AppState.ERROR);
  };

  const handleGenerate = useCallback(async (params: GenerateVideoParams) => {
    if (window.aistudio) {
      try {
        if (!(await window.aistudio.hasSelectedApiKey())) {
          setShowApiKeyDialog(true);
          return;
        }
      } catch (error) {
        console.warn(
          'aistudio.hasSelectedApiKey check failed, assuming no key selected.',
          error,
        );
        setShowApiKeyDialog(true);
        return;
      }
    }

    setAppState(AppState.LOADING);
    setErrorMessage(null);
    setLastConfig(params);
    setInitialFormValues(null);

    try {
      const {objectUrl, blob, video} = await generateVideo(params);
      setVideoUrl(objectUrl);
      setLastVideoBlob(blob);
      setLastVideoObject(video);
      setAppState(AppState.SUCCESS);
    } catch (error) {
      console.error('Video generation failed:', error);
      const errorMessage =
        error instanceof Error ? error.message : 'An unknown error occurred.';

      let userFriendlyMessage = `Video generation failed: ${errorMessage}`;
      let shouldOpenDialog = false;

      if (typeof errorMessage === 'string') {
        if (errorMessage.includes('Requested entity was not found.')) {
          userFriendlyMessage =
            'Model not found. This can be caused by an invalid API key or permission issues. Please check your API key.';
          shouldOpenDialog = true;
        } else if (
          errorMessage.includes('API_KEY_INVALID') ||
          errorMessage.includes('API key not valid') ||
          errorMessage.toLowerCase().includes('permission denied') ||
          errorMessage.includes('403')
        ) {
          userFriendlyMessage =
            'Your API key is invalid or lacks permissions. Please select a valid, billing-enabled API key.';
          shouldOpenDialog = true;
        }
      }

      setErrorMessage(userFriendlyMessage);
      setAppState(AppState.ERROR);

      if (shouldOpenDialog) {
        setShowApiKeyDialog(true);
      }
    }
  }, []);

  const handleRetry = useCallback(() => {
    if (lastConfig) {
      handleGenerate(lastConfig);
    }
  }, [lastConfig, handleGenerate]);

  const handleApiKeyDialogContinue = async () => {
    setShowApiKeyDialog(false);
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
    }
    if (appState === AppState.ERROR && lastConfig) {
      handleRetry();
    }
  };

  const handleNewVideo = useCallback(() => {
    setAppState(AppState.IDLE);
    setVideoUrl(null);
    setErrorMessage(null);
    setLastConfig(null);
    setLastVideoObject(null);
    setLastVideoBlob(null);
    setInitialFormValues(null);
  }, []);

  const handleTryAgainFromError = useCallback(() => {
    if (lastConfig) {
      setInitialFormValues(lastConfig);
      setAppState(AppState.IDLE);
      setErrorMessage(null);
    } else {
      handleNewVideo();
    }
  }, [lastConfig, handleNewVideo]);

  const handleExtend = useCallback(async () => {
    if (lastConfig && lastVideoBlob && lastVideoObject) {
      try {
        const file = new File([lastVideoBlob], 'last_video.mp4', {
          type: lastVideoBlob.type,
        });
        const videoFile: VideoFile = {file, base64: ''};

        setInitialFormValues({
          ...lastConfig,
          mode: GenerationMode.EXTEND_VIDEO,
          prompt: '', 
          inputVideo: videoFile, 
          inputVideoObject: lastVideoObject, 
          resolution: Resolution.P720, 
          startFrame: null,
          endFrame: null,
          referenceImages: [],
          styleImage: null,
          isLooping: false,
        });

        setAppState(AppState.IDLE);
        setVideoUrl(null);
        setErrorMessage(null);
      } catch (error) {
        console.error('Failed to process video for extension:', error);
        const message =
          error instanceof Error ? error.message : 'An unknown error occurred.';
        showStatusError(`Failed to prepare video for extension: ${message}`);
      }
    }
  }, [lastConfig, lastVideoBlob, lastVideoObject]);

  const renderError = (message: string) => (
    <div className="text-center bg-red-900/20 border border-red-500/50 p-8 rounded-2xl backdrop-blur-md">
      <h2 className="text-2xl font-bold text-red-400 mb-4">Generation Failed</h2>
      <p className="text-red-300 mb-6 max-w-md mx-auto">{message}</p>
      <button
        onClick={handleTryAgainFromError}
        className="px-8 py-3 bg-red-600/80 hover:bg-red-600 text-white font-semibold rounded-xl transition-all shadow-lg shadow-red-900/20">
        Try Again
      </button>
    </div>
  );

  const canExtend = lastConfig?.resolution === Resolution.P720;

  return (
    <div className="min-h-screen bg-[#0a0a0f] text-gray-200 flex flex-col font-sans overflow-x-hidden relative selection:bg-indigo-500/30">
      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute top-[-20%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/20 rounded-full blur-[120px]" />
        <div className="absolute bottom-[-20%] right-[-10%] w-[50%] h-[50%] bg-violet-900/10 rounded-full blur-[120px]" />
      </div>

      {showApiKeyDialog && (
        <ApiKeyDialog onContinue={handleApiKeyDialogContinue} />
      )}

      {/* Header */}
      <header className="py-5 px-6 sm:px-10 flex items-center justify-between border-b border-white/5 bg-[#0a0a0f]/80 backdrop-blur-md sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-violet-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </div>
          <h1 className="text-xl sm:text-2xl font-bold tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-400">
            Видео Студия
          </h1>
        </div>

        <div className="flex items-center gap-4">
          <div className="hidden sm:flex items-center gap-2 px-4 py-2 bg-white/5 rounded-full border border-white/10">
            <WalletIcon className="w-4 h-4 text-violet-400" />
            <span className="text-sm font-medium text-gray-300">Баланс: 106,789</span>
          </div>
          <button className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 text-sm font-medium rounded-full transition-colors border border-white/10">
            <PlusIcon className="w-4 h-4" />
            <span className="hidden sm:inline">Пополнить</span>
          </button>
        </div>
      </header>

      <main className="w-full max-w-5xl mx-auto flex-grow flex flex-col p-4 sm:p-8 relative z-10">
        {appState === AppState.IDLE ? (
          <div className="flex-grow flex flex-col justify-center animate-fade-in-up">
             <PromptForm
                onGenerate={handleGenerate}
                initialValues={initialFormValues}
              />
          </div>
        ) : (
          <div className="flex-grow flex items-center justify-center min-h-[600px]">
            {appState === AppState.LOADING && <LoadingIndicator />}
            {appState === AppState.SUCCESS && videoUrl && (
              <VideoResult
                videoUrl={videoUrl}
                onRetry={handleRetry}
                onNewVideo={handleNewVideo}
                onExtend={handleExtend}
                canExtend={canExtend}
                aspectRatio={lastConfig?.aspectRatio || AspectRatio.LANDSCAPE}
              />
            )}
            {appState === AppState.SUCCESS &&
              !videoUrl &&
              renderError(
                'Video generated, but URL is missing. Please try again.',
              )}
            {appState === AppState.ERROR &&
              errorMessage &&
              renderError(errorMessage)}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
*/
import {Video} from '@google/genai';
import React, {useCallback, useEffect, useRef, useState} from 'react';
import {
  AspectRatio,
  GenerateVideoParams,
  GenerationMode,
  ImageFile,
  Resolution,
  VeoModel,
  VideoFile,
  VideoStyle,
} from '../types';
import {
  ArrowRightIcon,
  ChevronDownIcon,
  FilmIcon,
  FramesModeIcon,
  PlusIcon,
  ReferencesModeIcon,
  SparklesIcon,
  TextModeIcon,
  WandIcon,
  XMarkIcon,
  TvIcon,
  SlidersHorizontalIcon
} from './icons';

interface PromptFormProps {
  onGenerate: (params: GenerateVideoParams) => void;
  initialValues?: GenerateVideoParams | null;
}

const ImageUpload: React.FC<{
  onSelect: (image: ImageFile) => void;
  onRemove?: () => void;
  image?: ImageFile | null;
  label: React.ReactNode;
  className?: string;
}> = ({onSelect, onRemove, image, label, className = "w-28 h-20"}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  const fileToBase64 = <T extends {file: File; base64: string}>(
    file: File,
  ): Promise<T> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        if (base64) {
          resolve({file, base64} as T);
        } else {
          reject(new Error('Failed to read file as base64.'));
        }
      };
      reader.onerror = (error) => reject(error);
      reader.readAsDataURL(file);
    });
  };
  const fileToImageFile = (file: File): Promise<ImageFile> =>
    fileToBase64<ImageFile>(file);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        const imageFile = await fileToImageFile(file);
        onSelect(imageFile);
      } catch (error) {
        console.error('Error converting file:', error);
      }
    }
    if (inputRef.current) {
      inputRef.current.value = '';
    }
  };

  if (image) {
    return (
      <div className={`relative group ${className}`}>
        <img
          src={URL.createObjectURL(image.file)}
          alt="preview"
          className="w-full h-full object-cover rounded-lg shadow-inner border border-white/10"
        />
        <button
          type="button"
          onClick={onRemove}
          className="absolute top-1 right-1 w-6 h-6 bg-black/60 hover:bg-black/80 rounded-full flex items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-opacity"
          aria-label="Remove image">
          <XMarkIcon className="w-3 h-3" />
        </button>
      </div>
    );
  }

  return (
    <button
      type="button"
      onClick={() => inputRef.current?.click()}
      className={`${className} bg-white/5 hover:bg-white/10 border border-dashed border-gray-600 rounded-lg flex flex-col items-center justify-center text-gray-400 hover:text-white transition-all`}>
      <PlusIcon className="w-5 h-5 mb-1" />
      <span className="text-[10px] text-center px-1">{label}</span>
      <input
        type="file"
        ref={inputRef}
        onChange={handleFileChange}
        accept="image/*"
        className="hidden"
      />
    </button>
  );
};

const PromptForm: React.FC<PromptFormProps> = ({
  onGenerate,
  initialValues,
}) => {
  const [prompt, setPrompt] = useState(initialValues?.prompt ?? '');
  const [model, setModel] = useState<VeoModel>(
    initialValues?.model ?? VeoModel.VEO_FAST,
  );

  // UI State for the "Fake" models to show selection state, 
  // but mapped to real Veo models under the hood.
  const [selectedChip, setSelectedChip] = useState<string>('veo-fast');

  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(
    initialValues?.aspectRatio ?? AspectRatio.PORTRAIT,
  );
  const [resolution, setResolution] = useState<Resolution>(
    initialValues?.resolution ?? Resolution.P720,
  );
  const [generationMode, setGenerationMode] = useState<GenerationMode>(
    initialValues?.mode ?? GenerationMode.TEXT_TO_VIDEO,
  );
  const [startFrame, setStartFrame] = useState<ImageFile | null>(
    initialValues?.startFrame ?? null,
  );
  const [endFrame, setEndFrame] = useState<ImageFile | null>(
    initialValues?.endFrame ?? null,
  );
  const [referenceImages, setReferenceImages] = useState<ImageFile[]>(
    initialValues?.referenceImages ?? [],
  );
  const [style, setStyle] = useState<VideoStyle>(VideoStyle.REALISTIC);
  const [duration, setDuration] = useState<string>('5s');

  const [isLooping, setIsLooping] = useState(initialValues?.isLooping ?? false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (initialValues) {
      setPrompt(initialValues.prompt ?? '');
      setModel(initialValues.model ?? VeoModel.VEO_FAST);
      setAspectRatio(initialValues.aspectRatio ?? AspectRatio.PORTRAIT);
      setGenerationMode(initialValues.mode ?? GenerationMode.TEXT_TO_VIDEO);
      // ... restore other values
    }
  }, [initialValues]);

  useEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(textarea.scrollHeight, 120)}px`;
    }
  }, [prompt]);

  const handleChipSelect = (chipId: string) => {
    setSelectedChip(chipId);
    if (chipId === 'veo-fast') setModel(VeoModel.VEO_FAST);
    else if (chipId === 'veo-pro') setModel(VeoModel.VEO);
    else setModel(VeoModel.VEO); // Fallback for Sora/Kling to Veo Pro
  };

  const handleMagicEnhance = () => {
    if (!prompt) return;
    const enhancements = [
      "cinematic lighting, 8k resolution, highly detailed",
      "cyberpunk atmosphere, neon lights, rainy street",
      "photorealistic, depth of field, ray tracing",
      "studio quality, sharp focus, professional color grading"
    ];
    const randomEnhancement = enhancements[Math.floor(Math.random() * enhancements.length)];
    setPrompt((prev) => `${prev}, ${randomEnhancement}`);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onGenerate({
      prompt,
      model,
      aspectRatio,
      resolution,
      mode: generationMode,
      startFrame,
      endFrame,
      referenceImages,
      style,
      duration,
      isLooping,
      inputVideoObject: initialValues?.inputVideoObject
    });
  };

  const ModelChip = ({id, label, subLabel, icon}: {id: string, label: string, subLabel?: string, icon?: React.ReactNode}) => (
    <button
      type="button"
      onClick={() => handleChipSelect(id)}
      className={`relative flex flex-col items-start p-4 rounded-xl border transition-all duration-200 w-full text-left
        ${selectedChip === id 
          ? 'bg-[#1a1a24] border-violet-500/50 shadow-[0_0_15px_rgba(139,92,246,0.15)]' 
          : 'bg-[#121216] border-white/5 hover:bg-[#1a1a1f] hover:border-white/10'
        }`}
    >
      <div className="flex items-center justify-between w-full mb-2">
        {icon}
        {selectedChip === id && <div className="w-2 h-2 rounded-full bg-violet-500 shadow-[0_0_8px_rgba(139,92,246,0.8)]"></div>}
      </div>
      <span className={`text-sm font-semibold ${selectedChip === id ? 'text-white' : 'text-gray-300'}`}>
        {label}
      </span>
      {subLabel && (
        <span className="text-[10px] uppercase tracking-wider font-medium mt-1 px-1.5 py-0.5 rounded bg-white/5 text-gray-400">
          {subLabel}
        </span>
      )}
    </button>
  );

  return (
    <form onSubmit={handleSubmit} className="w-full max-w-4xl mx-auto space-y-8">

      {/* 1. Model Selection */}
      <div className="space-y-3">
        <label className="text-gray-400 text-sm font-medium ml-1">Выберите AI модель</label>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <ModelChip 
            id="veo-fast" 
            label="Veo 3.1 Fast" 
            subLabel="Быстрый" 
            icon={<SparklesIcon className="w-5 h-5 text-indigo-400" />}
          />
          <ModelChip 
            id="veo-pro" 
            label="Veo 3.1 Quality" 
            subLabel="Качество" 
            icon={<SparklesIcon className="w-5 h-5 text-purple-400" />} 
          />
          <ModelChip 
            id="sora" 
            label="Sora 2 Pro" 
            subLabel="Beta" 
            icon={<FilmIcon className="w-5 h-5 text-gray-500" />} 
          />
          <ModelChip 
            id="kling" 
            label="Kling 2.5 Turbo" 
            subLabel="Реалистик" 
            icon={<TvIcon className="w-5 h-5 text-gray-500" />} 
          />
        </div>
      </div>

      {/* 2. Prompt Area */}
      <div className="space-y-3">
        <div className="flex justify-between items-center px-1">
          <label className="text-gray-400 text-sm font-medium">Промт</label>
          <div className="flex gap-2 text-xs">
             <button type="button" onClick={() => handleMagicEnhance} className="flex items-center gap-1 text-violet-400 hover:text-violet-300 transition-colors">
               <WandIcon className="w-3 h-3" />
               <span>Авто-улучшение</span>
