          video: { uri: simulationVideoUrl } as Video,
          isSimulation: true
        };
      } catch (simError) {
        console.error("Simulation fallback failed:", simError);
        throw new Error('Simulation fallback failed (Network error accessing sample video). Please check your internet connection.');
      }
    }

    throw error;
