import {
  GoogleGenAI,
  Video,
  VideoGenerationReferenceImage,
  VideoGenerationReferenceType,
} from '@google/genai';
import {GenerateVideoParams, GenerationMode} from '../types';

export const generateVideo = async (
  params: GenerateVideoParams,
): Promise<{objectUrl: string; blob: Blob; uri: string; video: Video; isSimulation?: boolean}> => {
  console.log('Starting video generation (Vertex AI) with params:', params);

  const apiKey = process.env.API_KEY;

  // Initialize with Vertex AI configuration as requested
  // Using the specific project and location provided
  const ai = new GoogleGenAI({
    vertexAI: {
      project: 'vertex-ai-runner-485313',
      location: 'us-central1',
    },
    // We pass the key here. Depending on the environment/SDK version, 
    // this might be treated as an API key for Vertex or a bearer token.
    apiKey: apiKey 
  });

  const config: any = {
    numberOfVideos: 1,
    resolution: params.resolution,
  };

  if (params.mode !== GenerationMode.EXTEND_VIDEO) {
    config.aspectRatio = params.aspectRatio;
  }

  const generateVideoPayload: any = {
    model: params.model,
    config: config,
  };

  // Enhance prompt with Style and Duration info
  let enhancedPrompt = params.prompt;
  if (params.style) {
    enhancedPrompt += ` . Style: ${params.style}`;
  }
  if (params.duration) {
    // Vertex Veo usually expects durationSeconds in config, but we'll keep prompt augmentation for safety
    enhancedPrompt += ` . Duration: ${params.duration}`;
  }

  if (enhancedPrompt) {
    generateVideoPayload.prompt = enhancedPrompt;
  }

  if (params.mode === GenerationMode.FRAMES_TO_VIDEO) {
    if (params.startFrame) {
      generateVideoPayload.image = {
        imageBytes: params.startFrame.base64,
        mimeType: params.startFrame.file.type,
      };
    }

    const finalEndFrame = params.isLooping
      ? params.startFrame
      : params.endFrame;
    if (finalEndFrame) {
      generateVideoPayload.config.lastFrame = {
        imageBytes: finalEndFrame.base64,
        mimeType: finalEndFrame.file.type,
      };
    }
  } else if (params.mode === GenerationMode.REFERENCES_TO_VIDEO) {
    const referenceImagesPayload: VideoGenerationReferenceImage[] = [];

    if (params.referenceImages) {
      for (const img of params.referenceImages) {
        referenceImagesPayload.push({
          image: {
            imageBytes: img.base64,
            mimeType: img.file.type,
          },
          referenceType: VideoGenerationReferenceType.ASSET,
        });
      }
    }

    if (referenceImagesPayload.length > 0) {
      generateVideoPayload.config.referenceImages = referenceImagesPayload;
    }
  } else if (params.mode === GenerationMode.EXTEND_VIDEO) {
    if (params.inputVideoObject) {
      generateVideoPayload.video = params.inputVideoObject;
    } else {
      throw new Error('An input video object is required to extend a video.');
    }
  }

  console.log('Submitting Vertex AI video request...', generateVideoPayload);

  try {
    let operation = await ai.models.generateVideos(generateVideoPayload);
    console.log('Vertex AI operation started:', operation);

    while (!operation.done) {
      await new Promise((resolve) => setTimeout(resolve, 10000));
      console.log('...Vertex AI Generating...');
      operation = await ai.operations.getVideosOperation({operation: operation});
    }

    if (operation?.response) {
      const videos = operation.response.generatedVideos;

      if (!videos || videos.length === 0) {
        throw new Error('No videos were generated from Vertex AI.');
      }

      const firstVideo = videos[0];
      // Vertex AI response structure might differ slightly, but SDK normalizes .video.uri usually
      const uri = firstVideo?.video?.uri || (firstVideo as any).gcsUri; 

      if (!uri) {
        throw new Error('Generated video is missing a URI.');
      }

      const videoObject = firstVideo.video || { uri: uri };

      const url = decodeURIComponent(uri);
      console.log('Fetching video from:', url);

      // Vertex AI typically returns GCS URIs (gs://) or specialized HTTPS links.
      // If it's a gs:// URI, we can't fetch it directly in browser without a signed URL service.
      // However, @google/genai often returns a downloadable https link if available.

      let fetchUrl = url;
      if (url.startsWith('gs://')) {
          throw new Error(`Received GCS URI (${url}) which cannot be downloaded directly in the browser. Please check backend configuration.`);
      }

      // Only append key if it's a googleapis URL that needs auth and is NOT a storage.googleapis.com public link
      if (url.includes('googleapis.com') && !url.includes('storage.googleapis.com')) {
         fetchUrl = `${url}&key=${apiKey}`;
      }

      const res = await fetch(fetchUrl);

      if (!res.ok) {
        throw new Error(`Failed to fetch video: ${res.status} ${res.statusText}`);
      }

      const videoBlob = await res.blob();
      const objectUrl = URL.createObjectURL(videoBlob);

      return {objectUrl, blob: videoBlob, uri: url, video: videoObject, isSimulation: false};
    } else {
      console.error('Operation failed:', operation);
      throw new Error('Vertex AI operation failed to produce video.');
    }
  } catch (error: any) {
    console.warn('Vertex AI Call Failed', error);

    let errorString = '';
    try {
        errorString += String(error) + ' '; 
        errorString += JSON.stringify(error) + ' ';
    } catch(e) {}
    const errLower = errorString.toLowerCase();

    // Propagate permission errors to trigger the API Key dialog in UI
    if (
      errLower.includes('403') || 
      errLower.includes('permission_denied') || 
      errLower.includes('permission denied') ||
      errLower.includes('does not have permission') ||
      errLower.includes('requested entity was not found') ||
      errLower.includes('unauthenticated')
    ) {
        throw new Error(`Vertex AI Permission Error: ${errorString.includes('message') ? (error as any).message : 'Access Denied (403)'}`);
    }

    throw error;
  }
};

