const getCleanApiKey = () => {
  let apiKey = process.env.API_KEY || '';
  if (apiKey.includes(' ')) {
    apiKey = apiKey.split(' ')[0];
  }
  if (apiKey.includes('@')) {
    const match = apiKey.match(/^(AIza[a-zA-Z0-9_\-]+)/);
    if (match) {
        apiKey = match[1];
    }
  }
  return apiKey.trim();
}

export const testVertexConnection = async (log: (msg: string, type?: 'info' | 'error' | 'success') => void) => {
    log('Initializing Vertex AI Diagnostic Test...', 'info');

    const apiKey = getCleanApiKey();
    log(`API Key detected: ${apiKey ? 'YES (Length: ' + apiKey.length + ')' : 'NO'}`, apiKey ? 'info' : 'error');
    if (apiKey) {
      log(`API Key prefix: ${apiKey.substring(0, 8)}...`, 'info');
    }

    const project = 'vertex-ai-runner-485313';
    const location = 'us-central1';

    log(`Configuring Vertex AI Client:`, 'info');
    log(`Project: ${project}`, 'info');
    log(`Location: ${location}`, 'info');

    const ai = new GoogleGenAI({
      vertexAI: {
        project: project,
        location: location,
      },
      apiKey: apiKey 
    });

    try {
        log('Attempting to contact Vertex AI (Probe Model: gemini-1.5-flash-002)...', 'info');
        // We use a cheap/fast text model to verify connectivity and auth before trying Veo
        const response = await ai.models.generateContent({
            model: 'gemini-1.5-flash-002',
            contents: 'Reply with "Connected" if you receive this.',
        });

        const text = response.text;
        log(`Response received: "${text}"`, 'success');
        log('Connectivity Check Passed! Vertex AI is reachable.', 'success');
    } catch (error: any) {
        log('Connectivity Check Failed.', 'error');
        log(`Error Name: ${error.name}`, 'error');
        log(`Error Message: ${error.message}`, 'error');
        if (error.stack) {
            console.error(error);
        }

        // Specific advice based on error
        const msg = error.message.toLowerCase();
        if (msg.includes('403') || msg.includes('permission')) {
            log('Diagnosis: Permission Denied. Check if the API Key has access to this specific GCP Project and if the Vertex AI API is enabled.', 'error');
        } else if (msg.includes('404') || msg.includes('not found')) {
             log('Diagnosis: Model or Project Not Found. Verify Project ID and Region.', 'error');
        }
    }
};

export const generateVideo = async (
  params: GenerateVideoParams,
): Promise<{objectUrl: string; blob: Blob; uri: string; video: Video; isSimulation?: boolean}> => {
  console.log('Starting video generation (Vertex AI) with params:', params);

  const apiKey = getCleanApiKey();

  // Initialize with Vertex AI configuration
  // The SDK will route to Vertex AI endpoints using the provided project/location
  const ai = new GoogleGenAI({
    vertexAI: {
      project: 'vertex-ai-runner-485313',
      location: 'us-central1',
    },
    apiKey: apiKey 
  });

  // Parse duration
  let durationSeconds = 5;
  if (params.duration) {
    const parsed = parseInt(params.duration);
    if (!isNaN(parsed)) {
      durationSeconds = parsed;
    }
  }

  const config: any = {
    numberOfVideos: 1,
    resolution: params.resolution,
    // Note: generateAudio is removed as it causes "parameter not supported" errors in the current API version.
    // Audio is typically generated by default if the prompt implies it.
    aspectRatio: params.aspectRatio
  };

  // Only add durationSeconds if strictly needed, some preview models might be sensitive to it.
  // We'll include it for now as Vertex usually supports it.
  config.durationSeconds = durationSeconds;

  const generateVideoPayload: any = {
    model: params.model,
    config: config,
  };

  // Construct prompt
  let enhancedPrompt = params.prompt;
  if (params.style) {
    enhancedPrompt += ` . Style: ${params.style}`;
  }

  if (enhancedPrompt) {
    generateVideoPayload.prompt = enhancedPrompt;
  }

  if (params.mode === GenerationMode.FRAMES_TO_VIDEO) {
    if (params.startFrame) {
      generateVideoPayload.image = {
        imageBytes: params.startFrame.base64,
        mimeType: params.startFrame.file.type,
      };
    }

    const finalEndFrame = params.isLooping
      ? params.startFrame
      : params.endFrame;
    if (finalEndFrame) {
      generateVideoPayload.config.lastFrame = {
        imageBytes: finalEndFrame.base64,
        mimeType: finalEndFrame.file.type,
      };
    }
  } else if (params.mode === GenerationMode.REFERENCES_TO_VIDEO) {
    const referenceImagesPayload: VideoGenerationReferenceImage[] = [];

    if (params.referenceImages) {
      for (const img of params.referenceImages) {
        referenceImagesPayload.push({
          image: {
            imageBytes: img.base64,
            mimeType: img.file.type,
          },
          referenceType: VideoGenerationReferenceType.ASSET,
        });
      }
    }

    if (referenceImagesPayload.length > 0) {
      generateVideoPayload.config.referenceImages = referenceImagesPayload;
    }
  } else if (params.mode === GenerationMode.EXTEND_VIDEO) {
    if (params.inputVideoObject) {
      generateVideoPayload.video = params.inputVideoObject;
    } else {
      throw new Error('An input video object is required to extend a video.');
    }
  }

  console.log('Submitting Vertex AI video request...', {
     model: generateVideoPayload.model,
     project: 'vertex-ai-runner-485313',
     config: generateVideoPayload.config
  });

  try {
    let operation = await ai.models.generateVideos(generateVideoPayload);
    console.log('Vertex AI operation started:', operation);

    while (!operation.done) {
      await new Promise((resolve) => setTimeout(resolve, 10000));
      console.log('...Vertex AI Generating...');
      operation = await ai.operations.getVideosOperation({operation: operation});
    }

    if (operation?.response) {
      const videos = operation.response.generatedVideos;

      if (!videos || videos.length === 0) {
        throw new Error('No videos were generated from Vertex AI.');
      }

      const firstVideo = videos[0];
      const uri = firstVideo?.video?.uri || (firstVideo as any).gcsUri; 

      if (!uri) {
        throw new Error('Generated video is missing a URI.');
      }

      const videoObject = firstVideo.video || { uri: uri };
      const url = decodeURIComponent(uri);
      console.log('Fetching video from:', url);

      let fetchUrl = url;
      if (url.startsWith('gs://')) {
          throw new Error(`The model returned a GCS URI (${url}). This application requires a public HTTP link to display the video. Please check if your bucket is public or if the API can return a download URL.`);
      }

      // Append API Key for authentication if it's a Google API URL
      if (url.includes('googleapis.com') && !url.includes('storage.googleapis.com')) {
         fetchUrl = `${url}&key=${apiKey}`;
      }

      const res = await fetch(fetchUrl);

      if (!res.ok) {
        throw new Error(`Failed to fetch video content: ${res.status} ${res.statusText}`);
      }

      const videoBlob = await res.blob();
      const objectUrl = URL.createObjectURL(videoBlob);

      return {objectUrl, blob: videoBlob, uri: url, video: videoObject, isSimulation: false};
    } else {
      console.error('Operation failed:', operation);
      throw new Error('Vertex AI operation failed to produce video.');
    }
  } catch (error: any) {
    console.warn('Vertex AI Call Failed', error);

    let errorString = '';
    try {
        errorString += String(error) + ' '; 
        errorString += JSON.stringify(error) + ' ';
    } catch(e) {}
    const errLower = errorString.toLowerCase();

    // Propagate permission errors to trigger the API Key dialog in UI
    if (
      errLower.includes('403') || 
      errLower.includes('permission_denied') || 
      errLower.includes('permission denied') ||
      errLower.includes('does not have permission') ||
      errLower.includes('requested entity was not found') ||
      errLower.includes('unauthenticated')
    ) {
        throw new Error(`Vertex AI Permission Error: ${errorString.includes('message') ? (error as any).message : 'Access Denied (403)'}`);
    }

    throw error;
  }
};

