                        <div className="text-[10px] text-purple-300 uppercase font-bold mb-1">Service Account:</div>
                        <code className="text-purple-100 font-mono break-all select-all">vertexairunner12@vertex-ai-runner-485313.iam.gserviceaccount.com</code>
                    </div>
                </div>
            </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-white/5 bg-[#1a1a24] flex justify-end gap-3">
           <button 
             onClick={onClose}
             className="px-4 py-2 text-gray-400 hover:text-white text-sm"
           >
             Cancel
           </button>
           <button 
             onClick={handleSaveAndClose}
             className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-semibold rounded-lg transition-all shadow-lg shadow-indigo-500/20"
           >
             {hasChanged ? 'Сохранить и Продолжить' : 'Продолжить'}
           </button>
        </div>

      </div>
    </div>
  );
};

