import React, { useState, useEffect, useRef } from 'react';
import { XMarkIcon, ActivityIcon, ArrowPathIcon } from './icons';
import { testVertexConnection } from '../services/geminiService';
import { VertexConnectionConfig } from '../types';

interface DiagnosticsModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: VertexConnectionConfig;
}

interface LogEntry {
  id: number;
  message: string;
  type: 'info' | 'error' | 'success';
  timestamp: string;
}

const DiagnosticsModal: React.FC<DiagnosticsModalProps> = ({ isOpen, onClose, config }) => {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [isRunning, setIsRunning] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const hasAutoRunRef = useRef(false);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs]);

  // Auto-run tests when opened for the first time
  useEffect(() => {
    if (isOpen && !hasAutoRunRef.current) {
        hasAutoRunRef.current = true;
        handleRunTest();
    }
  }, [isOpen]);

  const addLog = (message: string, type: 'info' | 'error' | 'success' = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [...prev, { id: Date.now(), message, type, timestamp }]);
  };

  const handleRunTest = async () => {
    if (isRunning) return;
    setIsRunning(true);
    setLogs([]); // Clear previous logs
    addLog(`Starting Diagnostics for ${config.project} (${config.location})...`, 'info');

    try {
        await testVertexConnection(config, (msg, type) => addLog(msg, type));
    } catch (e) {
        addLog('Unexpected test harness error.', 'error');
        console.error(e);
    } finally {
        setIsRunning(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[120] backdrop-blur-sm p-4">
      <div className="bg-[#0f0f13] border border-gray-700 rounded-2xl w-full max-w-2xl shadow-2xl flex flex-col max-h-[80vh] overflow-hidden">

        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-800 bg-[#16161e]">
          <div className="flex items-center gap-2 text-white font-mono">
            <ActivityIcon className="w-5 h-5 text-green-400" />
            <span className="font-bold">Vertex AI Diagnostics</span>
          </div>
          <button 
            onClick={onClose}
            className="text-gray-400 hover:text-white transition-colors"
          >
            <XMarkIcon className="w-6 h-6" />
          </button>
        </div>

        {/* Console Output */}
        <div 
          ref={scrollRef}
          className="flex-grow p-4 overflow-y-auto font-mono text-sm space-y-2 bg-black/50"
        >
          {logs.length === 0 && !isRunning && (
             <div className="text-gray-500 italic text-center mt-10">
                Initializing...
             </div>
          )}
          {logs.map((log) => (
            <div key={log.id} className="flex gap-3 animate-fade-in">
              <span className="text-gray-600 select-none">[{log.timestamp}]</span>
              <span className={`
                ${log.type === 'error' ? 'text-red-400 font-bold' : ''}
                ${log.type === 'success' ? 'text-green-400 font-bold' : ''}
                ${log.type === 'info' ? 'text-gray-300' : ''}
              `}>
                {log.message}
              </span>
            </div>
          ))}
          {isRunning && (
            <div className="flex gap-2 items-center text-gray-500 animate-pulse">
               <span className="w-2 h-4 bg-gray-500 inline-block"></span>
            </div>
          )}
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-gray-800 bg-[#16161e] flex justify-end gap-3">
           <button 
             onClick={onClose}
             className="px-4 py-2 text-gray-400 hover:text-white text-sm"
           >
             Close
           </button>
           <button
             onClick={handleRunTest}
             disabled={isRunning}
             className="flex items-center gap-2 px-5 py-2 bg-green-600 hover:bg-green-500 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-bold rounded-lg transition-all shadow-lg shadow-green-900/20"
           >
             <ArrowPathIcon className={`w-4 h-4 ${isRunning ? 'animate-spin' : ''}`} />
             {isRunning ? 'Testing...' : 'Run Connection Test'}
           </button>
        </div>

      </div>
    </div>
  );
};

export default DiagnosticsModal;

