import {
  GoogleGenAI,
  Video,
  VideoGenerationReferenceImage,
  VideoGenerationReferenceType,
} from '@google/genai';
import {GenerateVideoParams, GenerationMode, VertexConnectionConfig} from '../types';

const getCleanApiKey = () => {
  let apiKey = process.env.API_KEY || '';
  if (apiKey.includes(' ')) {
    apiKey = apiKey.split(' ')[0];
  }
  if (apiKey.includes('@')) {
    const match = apiKey.match(/^(AIza[a-zA-Z0-9_\-]+)/);
    if (match) {
        apiKey = match[1];
    }
  }
  return apiKey.trim();
}

export const testVertexConnection = async (
  config: VertexConnectionConfig,
  log: (msg: string, type?: 'info' | 'error' | 'success') => void
) => {
    log('Initializing Vertex AI Diagnostic Test...', 'info');

    const apiKey = getCleanApiKey();
    // Mask API key for security in logs, but show length to verify it's not empty or truncated
    const maskedKey = apiKey ? `${apiKey.substring(0, 4)}...${apiKey.substring(apiKey.length - 4)}` : 'NONE';
    log(`API Key detected: ${apiKey ? 'YES' : 'NO'} (Length: ${apiKey.length}, Value: ${maskedKey})`, apiKey ? 'info' : 'error');

    log(`Configuring Vertex AI Client:`, 'info');
    log(`Project: ${config.project}`, 'info');
    log(`Location: ${config.location}`, 'info');

    const ai = new GoogleGenAI({
      vertexAI: {
        project: config.project,
        location: config.location,
      },
      apiKey: apiKey 
    });

    // TEST 1: Text Generation (Connectivity Probe)
    // We use 'gemini-1.5-flash-001' specifically because generic aliases like 'gemini-1.5-flash'
    // sometimes fail to resolve in regions outside us-central1 (e.g., us-west1).
    try {
        log('--- Test 1: Connectivity Probe (gemini-1.5-flash-001) ---', 'info');
        const response = await ai.models.generateContent({
            model: 'gemini-1.5-flash-001',
            contents: 'Reply with "Connected" if you receive this.',
        });

        const text = response.text;
        log(`Response received: "${text}"`, 'success');
        log('Connectivity Check Passed! Vertex AI is reachable.', 'success');
    } catch (error: any) {
        log('Connectivity Check Failed.', 'error');

        let errorMsg = error.message || String(error);
        try {
           if (error.response) {
             const resp = await error.response.json();
             errorMsg = JSON.stringify(resp);
           }
        } catch (e) {}

        log(`Error: ${errorMsg}`, 'error');

        if (errorMsg.includes('404') || errorMsg.includes('not found')) {
             log('HINT: The model was not found in this region. Try switching Location to "us-central1" in the settings menu.', 'info');
        }

        // Stop here if basic connectivity fails
        return; 
    }

    // TEST 2: Veo Model Availability Check
    try {
        log('--- Test 2: Veo Model Access (veo-3-1-flash) ---', 'info');
        log('Verifying Veo Model configuration...', 'info');
        log('Model ID configured: veo-3-1-flash', 'info');
        log('Note: If generation fails with 404, please ensure "Veo" is enabled in the Vertex AI Model Garden.', 'info');

    } catch (error: any) {
         log(`Veo Model Check Warning: ${error.message}`, 'error');
    }
};

export const generateVideo = async (
  params: GenerateVideoParams,
  connectionConfig: VertexConnectionConfig
): Promise<{objectUrl: string; blob: Blob; uri: string; video: Video; isSimulation?: boolean}> => {
  const apiKey = getCleanApiKey();

  // Initialize with Vertex AI configuration from params
  const ai = new GoogleGenAI({
    vertexAI: {
      project: connectionConfig.project,
      location: connectionConfig.location,
    },
    apiKey: apiKey 
  });

  // Strict Parameter Parsing for Vertex AI Compliance

  // 1. Duration: Must be integer seconds
  // Default to 5 if parsing fails
  let durationSeconds = 5;
  if (params.duration) {
    // Remove 's' and parse to int
    const parsed = parseInt(params.duration.replace(/s/i, ''), 10);
    if (!isNaN(parsed)) {
      durationSeconds = parsed;
    }
  }

  // 2. Resolution: Ensure valid enum string (720p, 1080p)
  // Vertex often defaults to 720p if unspecified.
  const resolution = params.resolution || '720p';

  // 3. Aspect Ratio: Ensure valid format (16:9, 9:16, 1:1)
  const aspectRatio = params.aspectRatio || '16:9';

  const config: any = {
    // Flattened config structure for SDK
    numberOfVideos: 1,
    resolution: resolution,
    aspectRatio: aspectRatio,
    // Ensure this is a number
    durationSeconds: Number(durationSeconds), 
  };

  const generateVideoPayload: any = {
    model: params.model, 
    config: config,
  };

  // Construct prompt
  // Vertex AI Veo expects the prompt as a top-level string property
  let enhancedPrompt = params.prompt;
  if (params.style) {
    enhancedPrompt += ` . Style: ${params.style}`;
  }

  if (enhancedPrompt) {
    generateVideoPayload.prompt = enhancedPrompt;
  }

  // Handling Modes
  if (params.mode === GenerationMode.FRAMES_TO_VIDEO) {
    if (params.startFrame) {
      // SDK expects 'image' property for start frame
      generateVideoPayload.image = {
        imageBytes: params.startFrame.base64,
        mimeType: params.startFrame.file.type,
      };
    }

    const finalEndFrame = params.isLooping
      ? params.startFrame
      : params.endFrame;
    if (finalEndFrame) {
      // End frame goes in config
      generateVideoPayload.config.lastFrame = {
        imageBytes: finalEndFrame.base64,
        mimeType: finalEndFrame.file.type,
      };
    }
  } else if (params.mode === GenerationMode.REFERENCES_TO_VIDEO) {
    const referenceImagesPayload: VideoGenerationReferenceImage[] = [];

    if (params.referenceImages) {
      for (const img of params.referenceImages) {
        referenceImagesPayload.push({
          image: {
            imageBytes: img.base64,
            mimeType: img.file.type,
          },
          referenceType: VideoGenerationReferenceType.ASSET,
        });
      }
    }

    if (referenceImagesPayload.length > 0) {
      generateVideoPayload.config.referenceImages = referenceImagesPayload;
    }
  } else if (params.mode === GenerationMode.EXTEND_VIDEO) {
    if (params.inputVideoObject) {
      generateVideoPayload.video = params.inputVideoObject;
    } else {
      throw new Error('An input video object is required to extend a video.');
    }
  }

  // VERBOSE LOGGING FOR DIAGNOSTICS
  const logPayload = JSON.stringify({
      model: generateVideoPayload.model,
      targetProject: connectionConfig.project,
      targetLocation: connectionConfig.location,
      prompt: generateVideoPayload.prompt ? (generateVideoPayload.prompt.substring(0, 50) + '...') : undefined,
      config: generateVideoPayload.config,
      hasImage: !!generateVideoPayload.image,
      hasVideo: !!generateVideoPayload.video
  }, null, 2);

  console.log('%c VERTEX AI PAYLOAD: ', 'background: #222; color: #bada55', logPayload);

  try {
    let operation = await ai.models.generateVideos(generateVideoPayload);
    console.log('Vertex AI operation started ID:', operation.name);

    // POLLING LOOP
    while (!operation.done) {
      // Wait 10s between polls (Veo is slow)
      await new Promise((resolve) => setTimeout(resolve, 10000));
      console.log('...Polling Vertex AI Operation...');
      operation = await ai.operations.getVideosOperation({operation: operation});
    }

    if (operation?.response) {
      const videos = operation.response.generatedVideos;

      if (!videos || videos.length === 0) {
        throw new Error('Vertex AI reported success but returned no videos.');
      }

      const firstVideo = videos[0];
      // Normalize URI
      const uri = firstVideo?.video?.uri || (firstVideo as any).gcsUri || (firstVideo as any).uri; 

      if (!uri) {
        throw new Error('Generated video object is missing a URI property.');
      }

      const videoObject = firstVideo.video || { uri: uri };
      const url = decodeURIComponent(uri);
      console.log('Video URI received:', url);

      let fetchUrl = url;
      if (url.startsWith('gs://')) {
          // GCS URIs cannot be fetched by browser directly without a signed URL or proxy.
          // We will throw a helpful error if this happens, prompting backend config check.
          throw new Error(`The model returned a GCS URI (${url}). This application currently supports HTTPS download links only. Please check your Vertex AI output bucket configuration.`);
      }

      // Append API Key for Google API URLs to authorize the download
      if (url.includes('googleapis.com') && !url.includes('storage.googleapis.com')) {
         fetchUrl = `${url}&key=${apiKey}`;
      }

      const res = await fetch(fetchUrl);

      if (!res.ok) {
        throw new Error(`Failed to download video file: ${res.status} ${res.statusText}`);
      }

      const videoBlob = await res.blob();
      const objectUrl = URL.createObjectURL(videoBlob);

      return {objectUrl, blob: videoBlob, uri: url, video: videoObject, isSimulation: false};
    } else {
      console.error('Operation Error Result:', operation);
      const errMessage = (operation as any).error?.message || 'Unknown operation error';
      throw new Error(`Vertex AI Operation Failed: ${errMessage}`);
    }
  } catch (error: any) {
    console.warn('Vertex AI Call Exception:', error);

    let errorString = '';
    try {
        errorString = error.message || String(error);
        if (error.response) {
            errorString += ` (Status: ${error.response.status})`;
        }
    } catch(e) {}
    const errLower = errorString.toLowerCase();

    // Specific Error Handling
    if (errLower.includes('400') || errLower.includes('invalid argument')) {
         console.error('INVALID ARGUMENT - Check Console Log for Payload');
         throw new Error(`Vertex AI Validation Error (400). The model configuration might be incorrect for this specific model version. Details: ${errorString}`);
    }

    if (
      errLower.includes('403') || 
      errLower.includes('permission') || 
      errLower.includes('unauthenticated')
    ) {
        throw new Error(`Permission Denied (403). Ensure API Key has 'Vertex AI Administrator' or 'Vertex AI User' role on project '${connectionConfig.project}'.`);
    }

    if (errLower.includes('404') || errLower.includes('not found')) {
        throw new Error(`Model Not Found (404). Ensure Model ID '${params.model}' is enabled in Project '${connectionConfig.project}' and location '${connectionConfig.location}'.`);
    }

    throw error;
  }
};

